mapper.select:
select a.assessment_id, a.visitor_id, a.questionnaire_id, a.questionnaire_code, a.questionnaire_version, a.channel_code, a.client_platform, a.policy_version, a.consent_time, a.assessment_status, a.is_minor, a.current_screen, a.submitted_time, a.create_time, a.update_time, (select count(*) from jsonb_object_keys(a.answers)) as answer_count, p.undergrad_tier, p.gpa_percent, p.ielts_equiv_total, p.target_field_group, p.normalized_time from abr_assessment a left join abr_profile p on p.assessment_id = a.assessment_id where a.del_flag = '0'
AND a.assessment_id = #{assessmentId}
AND a.assessment_status = #{assessmentStatus}
AND a.channel_code = #{channelCode}
AND a.is_minor = #{isMinor}
AND a.create_time >= cast(#{params.beginTime} as date)
AND a.create_time < cast(#{params.endTime} as date) + interval '1 day'
order by a.assessment_id desc
